package com.mo.economy_system.target.forge1201.network;
import com.mo.economy_system.common.market.*;import com.mo.economy_system.common.network.RemoveSalesOrderMessage;import com.mo.economy_system.core.economy_system.market.MarketSavedData;import com.mo.economy_system.platform.EconomyServices;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.item.ItemStack;import net.minecraftforge.network.NetworkEvent;import java.util.*;import java.util.function.Supplier;
final class Forge1201RemoveSalesOrderHandler{
 static void handle(RemoveSalesOrderMessage m,Supplier<NetworkEvent.Context>s){NetworkEvent.Context n=s.get();ServerPlayer actor=n.getSender();if(actor!=null){MarketSavedData data=MarketSavedData.getInstance(actor.serverLevel());RemoveSalesOrderOutcome o=RemoveSalesOrderService.execute(m,new RemoveSalesOrderService.Context(actor.getUUID(),actor.hasPermissions(2),order->EconomyServices.platform().itemStacks().restoreSnapshot(order.item(),actor.serverLevel().registryAccess()).orElseThrow(),id->{ServerPlayer p=actor.server.getPlayerList().getPlayer(id);return p==null?Optional.empty():Optional.of(new Inv(p));},new Repo(data),RemoveSalesOrderService.FailureReporter.noop()));actor.sendSystemMessage(Component.translatable(RemoveSalesOrderFeedback.key(o.result())));if(o.marketChanged())Forge1201MarketInvalidation.broadcast(actor);}n.setPacketHandled(true);}
 private record Repo(MarketSavedData d)implements RemoveSalesOrderService.Repository{public MarketOrder find(UUID id){return d.getOrder(id);}public SalesOrderRemovalResult removeSalesTransactional(UUID id){return d.removeSalesTransactional(id);}}
 private record Inv(ServerPlayer p)implements TransactionalInventory{public UUID ownerId(){return p.getUUID();}public boolean canAccept(Object o,int q){return capacity((ItemStack)o)>=q;}private int capacity(ItemStack t){long c=0;for(ItemStack x:p.getInventory().items){if(x.isEmpty())c+=t.getMaxStackSize();else if(EconomyServices.platform().itemStacks().sameItemAndData(x,t))c+=Math.max(0,x.getMaxStackSize()-x.getCount());}return(int)Math.min(Integer.MAX_VALUE,c);}public InventoryInsertionResult insert(Object o,int q){ItemStack t=((ItemStack)o).copy();t.setCount(1);Inventory i=p.getInventory();List<ItemStack>b=i.items.stream().map(ItemStack::copy).toList();int r=q;try{for(ItemStack x:i.items)if(r>0&&!x.isEmpty()&&EconomyServices.platform().itemStacks().sameItemAndData(x,t)){int a=Math.min(r,x.getMaxStackSize()-x.getCount());x.grow(a);r-=a;}for(int x=0;x<i.items.size()&&r>0;x++)if(i.items.get(x).isEmpty()){ItemStack z=t.copy();int a=Math.min(r,z.getMaxStackSize());z.setCount(a);i.setItem(x,z);r-=a;}if(r>0)return InventoryInsertionResult.failure(restore(b));i.setChanged();return InventoryInsertionResult.success(()->restore(b));}catch(RuntimeException e){return InventoryInsertionResult.failure(restore(b));}}private boolean restore(List<ItemStack>b){try{for(int x=0;x<b.size();x++)p.getInventory().setItem(x,b.get(x).copy());p.getInventory().setChanged();return true;}catch(RuntimeException e){return false;}}}
}
